{% extends "amoamancustom/templates/emails/_base_mail.html" %}
{% import "amoamancustom/templates/emails/_composants.html" as ui %}

{% set soustitre = doc.designation or doc.department %}
{% set mention_pied = "Vous recevez ce message parce qu'il concerne un collègue de votre société." %}

{% block titre %}{{ annees }} {{ "an" if annees == 1 else "ans" }} pour {{ doc.employee_name }}{% endblock %}
{% block preheader %}{{ doc.employee_name }} fête aujourd'hui son anniversaire professionnel.{% endblock %}

{% block contenu %}
{{ ui.p("Bonjour à toutes et à tous,") }}
{{ ui.p(doc.employee_name ~ " célèbre aujourd'hui " ~ annees ~ (" an" if annees == 1 else " ans") ~ " au sein d'Amoaman & Associés. L'occasion de saluer le chemin parcouru ensemble.") }}

{{ ui.details([
  ("Collaborateur", doc.employee_name),
  ("Service", doc.department),
  ("Poste", doc.designation),
  ("Arrivé le", frappe.utils.formatdate(doc.date_of_joining, "dd/MM/yyyy") if doc.date_of_joining else None),
  ("Ancienneté", (annees | string) ~ (" an" if annees == 1 else " ans")),
]) }}

{{ ui.p("Merci pour votre engagement, et belle continuation parmi nous.") }}
{% endblock %}
